// SPDX-License-Identifier: MIT
pragma solidity >=0.8.29;

import { FixedPointMathLib } from "solady/src/utils/FixedPointMathLib.sol";

/// @title LibMarkOracle
/// @notice Lighter-inspired mark price oracle using time-based EMA and median of three prices.
/// @dev Computes mark price as median(P1, P2, P3) where:
///      P1 = IndexPrice + clamp(EMA(ImpactPrice - IndexPrice), ±maxPremiumBps)
///      P2 = ImpactPrice (raw impact price from book depth)
///      P3 = ExternalPrice (from external oracle like Stork)
///
///      The EMA tracks raw, unclamped premiums. Clamping occurs only when computing P1 to prevent
///      extreme deviations from dominating the mark price while preserving EMA signal integrity.
///
///      Impact price is computed by simulating fills through the book for a target notional
///      amount scaled by leverage: impactNotional = baseNotional * maxLeverage.
///
///      The EMA uses continuous time-based decay rather than block-based smoothing to prevent
///      manipulation via block timing control on L2 sequencers.
library LibMarkOracle {
    using FixedPointMathLib for uint256;

    /// @notice Time-weighted EMA state for tracking premium/discount over time.
    /// @dev Uses continuous exponential decay: ema = numerator / denominator
    ///      numerator = numerator_old * exp(-dt/τ) + sample * dt
    ///      denominator = denominator_old * exp(-dt/τ) + dt
    ///      Premium is stored as signed int256 to represent both premium (positive) and discount (negative).
    ///      Using int256/uint256 (not int128/uint128) to prevent overflow when dt is large or after many updates.
    struct TimeEMAState {
        int256 numerator;
        uint256 denominator;
        uint64 lastUpdateTime;
    }

    /// @notice Configuration parameters for mark price computation.
    /// @dev All parameters are governance-updatable per market to adapt to changing liquidity conditions.
    struct Config {
        uint32 timeConstantSeconds;
        uint32 minUpdateInterval;
        uint16 maxPremiumBps;
    }

    /// @notice Updates the premium EMA with a new sample using time-weighted exponential decay.
    /// @dev On first update (denominator == 0), initializes the EMA to the sample value.
    ///      For subsequent updates, applies exponential decay based on elapsed time:
    ///      - Computes decay factor: exp(-dt/τ)
    ///      - Updates numerator: numerator_old * decay + sample * dt
    ///      - Updates denominator: denominator_old * decay + dt
    ///      The premium is stored raw without clamping to preserve signal integrity.
    ///      Clamping occurs at read time in computePriceInputs.
    ///      Note: minUpdateInterval gating is enforced by the caller (e.g. RISExOracle.syncMarkPriceEMA).
    /// @param emaState The EMA state storage pointer
    /// @param config The oracle configuration containing time constant
    /// @param premium The current raw premium (impactPrice - indexPrice), can be negative
    function updatePremiumEMA(
        TimeEMAState storage emaState,
        Config memory config,
        int256 premium
    ) internal {
        uint256 currentTime = block.timestamp;

        if (emaState.lastUpdateTime == 0) {
            emaState.numerator = premium;
            emaState.denominator = 1;
            emaState.lastUpdateTime = uint64(currentTime);
            return;
        }

        uint256 dt = currentTime - emaState.lastUpdateTime;

        int256 exponent = -int256((dt * FixedPointMathLib.WAD) / config.timeConstantSeconds);
        uint256 decay = uint256(FixedPointMathLib.expWad(exponent));

        int256 decayedNumerator = (emaState.numerator * int256(decay)) / int256(FixedPointMathLib.WAD);
        int256 newNumerator = decayedNumerator + (premium * int256(dt));

        uint256 decayedDenominator = (emaState.denominator * decay) / FixedPointMathLib.WAD;
        uint256 newDenominator = decayedDenominator + dt;

        emaState.numerator = newNumerator;
        emaState.denominator = newDenominator;
        emaState.lastUpdateTime = uint64(currentTime);
    }

    /// @notice Returns the current EMA premium value.
    /// @dev Returns 0 if EMA is uninitialized (denominator == 0).
    ///      The returned value can be negative (discount) or positive (premium).
    /// @param emaState The EMA state storage pointer
    /// @return The current EMA premium in WAD units
    function getEMAPremium(
        TimeEMAState storage emaState
    ) internal view returns (int256) {
        if (emaState.denominator == 0) return 0;
        return emaState.numerator / int256(emaState.denominator);
    }

    /// @notice Clamps a value between minimum and maximum bounds.
    /// @dev Used to limit premium deviation from index price as a circuit breaker.
    ///      Prevents extreme book manipulation from creating unbounded mark price deviation.
    /// @param value The value to clamp
    /// @param min The minimum bound
    /// @param max The maximum bound
    /// @return The clamped value
    function clamp(
        int256 value,
        int256 min,
        int256 max
    ) internal pure returns (int256) {
        if (value < min) return min;
        if (value > max) return max;
        return value;
    }

    /// @notice Returns the median of three values.
    /// @dev Used to compute mark price as median(P1, P2, P3).
    ///      Median provides robustness: requires 2/3 inputs to be corrupted for manipulation.
    ///      Handles all permutations of ordering without branches.
    /// @param a First value
    /// @param b Second value
    /// @param c Third value
    /// @return The median value
    function median3(
        uint256 a,
        uint256 b,
        uint256 c
    ) internal pure returns (uint256) {
        if (a > b) {
            if (b > c) return b;
            if (a > c) return c;
            return a;
        } else {
            if (a > c) return a;
            if (b > c) return c;
            return b;
        }
    }

    /// @notice Computes the two internal price inputs for mark price calculation.
    /// @dev P1 = indexPrice + clamp(EMA(premium), ±maxPremiumBps)
    ///      P2 = impactPrice (raw)
    ///      The EMA tracks raw premiums. Clamping occurs here at read time to prevent
    ///      extreme book manipulation from dominating the mark price while preserving
    ///      the EMA's ability to track genuine market trends.
    /// @param indexPrice The index price from external oracle
    /// @param impactPrice The impact price computed from book depth
    /// @param emaPremium The current raw EMA premium from state
    /// @param maxPremiumBps The maximum allowed premium deviation in basis points
    /// @return p1 Index-anchored premium price
    /// @return p2 Raw impact price
    function computePriceInputs(
        uint256 indexPrice,
        uint256 impactPrice,
        int256 emaPremium,
        uint16 maxPremiumBps
    ) internal pure returns (uint256 p1, uint256 p2) {
        p2 = impactPrice;

        int256 signedIndexPrice = int256(indexPrice);
        int256 maxDeviation = (signedIndexPrice * int256(uint256(maxPremiumBps))) / 10_000;
        int256 clampedPremium = clamp(emaPremium, -maxDeviation, maxDeviation);

        p1 = uint256(signedIndexPrice + clampedPremium);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.29;

import { Currency } from "src/libraries/types/Currency.sol";

/// @title IFeeWithdrawal
/// @notice Interface for contracts that hold tokens and can transfer trading fees
interface IFeeWithdrawal {
    /// @notice Emitted when the fee manager address is updated
    event FeeManagerUpdated(address indexed oldFeeManager, address indexed newFeeManager);

    /// @notice Transfers trading fees to a recipient
    /// @dev Only callable by the registered FeeManager contract
    /// @param token The token to transfer
    /// @param amount The amount to transfer (in token decimals)
    /// @param to The recipient address
    function transferTradingFees(
        Currency token,
        uint256 amount,
        address to
    ) external;

    /// @notice Sets the FeeManager address that is exclusively allowed to call transferTradingFees
    /// @dev Only callable by the AccessManager authority (restricted)
    /// @param feeManager The FeeManager contract address
    function setFeeManager(
        address feeManager
    ) external;
}

// SPDX-License-Identifier: MIT
pragma solidity >=0.8.29;

import { SafeCastLib } from "solady/src/utils/SafeCastLib.sol";

/// @title LibBlockEMA
/// @notice Gas-efficient exponential moving average for sub-second L2 chains.
/// @dev Single storage slot (~5K gas per update), immune to single-block manipulation.
///      Alpha and minBlocks are configurable per-deployment; callers pass them in.
/// @custom:security-contact security@risex.io
library LibBlockEMA {
    using SafeCastLib for *;

    /*//////////////////////////////////////////////////////////////
                                CONSTANTS
    //////////////////////////////////////////////////////////////*/

    uint256 internal constant WAD = 1e18;
    uint256 internal constant BPS = 10_000;

    /// @dev Default EMA smoothing factor: alpha = 0.1 * WAD = 1e17 (10% weight to new price)
    uint64 internal constant DEFAULT_ALPHA = 1e17;

    /// @dev Default minimum blocks before EMA is considered reliable for validation
    uint16 internal constant DEFAULT_MIN_BLOCKS = 20;

    /// @dev Maximum confidence score
    uint256 internal constant MAX_CONFIDENCE = 100;

    /*//////////////////////////////////////////////////////////////
                                 ERRORS
    //////////////////////////////////////////////////////////////*/

    /// @dev Spot price deviated too far from EMA
    error PriceDeviationTooHigh(uint256 spotPrice, uint256 ema, uint256 deviationBPS);

    /*//////////////////////////////////////////////////////////////
                              DATA STRUCTURES
    //////////////////////////////////////////////////////////////*/

    /// @dev Per-token EMA configuration: alpha (8B) + minBlocks (2B) + deviationThresholdBps (2B) = 12 bytes in 1 slot
    struct Config {
        uint64 alpha; // EMA smoothing factor (WAD scaled, 0 = use DEFAULT_ALPHA)
        uint16 minBlocks; // Minimum update count for reliability (0 = use DEFAULT_MIN_BLOCKS)
        uint16 deviationThresholdBps; // Max EMA deviation in BPS (0 = use global default)
    }

    /// @dev Packed into single 256-bit slot for gas efficiency
    /// Layout: [ema: 128 bits][lastBlock: 64 bits][updateCount: 64 bits]
    struct EmaState {
        uint128 ema; // Current EMA value (WAD scaled)
        uint64 lastBlock; // Last update block (uint64 safe: 584B years at 1 block/sec)
        uint64 updateCount; // Number of updates (for bootstrap detection)
    }

    /*//////////////////////////////////////////////////////////////
                              CORE FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /// @notice Update EMA with new price observation.
    /// @dev Called on every price fetch. ~5K gas (single SSTORE). Skips if same block.
    /// @param $ Storage pointer to EMA state
    /// @param newPrice New price observation (WAD scaled)
    /// @param alpha EMA smoothing factor (WAD scaled, 0 < alpha < WAD)
    function update(
        EmaState storage $,
        uint256 newPrice,
        uint64 alpha
    ) internal {
        // Skip if same block (no new information)
        if (block.number == $.lastBlock) return;

        uint128 currentEma = $.ema;

        if (currentEma == 0) {
            // Bootstrap: first price becomes EMA
            $.ema = newPrice.toUint128();
        } else {
            // EMA = alpha * newPrice + (1 - alpha) * oldEMA
            uint256 oneMinusAlpha = WAD - alpha;
            uint256 newEma = (alpha * newPrice + oneMinusAlpha * currentEma) / WAD;
            $.ema = newEma.toUint128();
        }

        $.lastBlock = block.number.toUint64();

        // Safe increment (will overflow after 2^64 updates - practically never)
        unchecked {
            $.updateCount++;
        }
    }

    /// @notice Get current EMA value.
    /// @param $ Storage pointer to EMA state
    /// @return Current EMA (0 if not initialized)
    function get(
        EmaState storage $
    ) internal view returns (uint256) {
        return $.ema;
    }

    /// @notice Check if EMA has sufficient history for reliable validation.
    /// @param $ Storage pointer to EMA state
    /// @param minBlocks Minimum update count for reliability
    /// @return True if enough updates have occurred
    function isReliable(
        EmaState storage $,
        uint16 minBlocks
    ) internal view returns (bool) {
        return $.updateCount >= minBlocks;
    }

    /// @notice Validate spot price against EMA. Reverts if deviation exceeds threshold.
    /// @dev During bootstrap (< minBlocks updates), validation passes.
    /// @param $ Storage pointer to EMA state
    /// @param spotPrice Current spot price to validate (WAD)
    /// @param maxDeviationBPS Maximum allowed deviation in basis points (e.g., 500 = 5%)
    /// @param minBlocks Minimum update count before validation enforced
    function validate(
        EmaState storage $,
        uint256 spotPrice,
        uint256 maxDeviationBPS,
        uint16 minBlocks
    ) internal view {
        uint256 ema = $.ema;

        // Allow any price during bootstrap (insufficient history)
        if (ema == 0 || $.updateCount < minBlocks) {
            return;
        }

        uint256 deviationBPS = calculateDeviationBPS(spotPrice, ema);

        require(deviationBPS <= maxDeviationBPS, PriceDeviationTooHigh(spotPrice, ema, deviationBPS));
    }

    /// @notice Get full EMA state for external queries.
    /// @param $ Storage pointer to EMA state
    /// @param minBlocks Minimum update count for reliability
    /// @return ema Current EMA value
    /// @return lastBlock Last update block
    /// @return updateCount Total updates
    /// @return reliable Whether EMA has sufficient history
    function getState(
        EmaState storage $,
        uint16 minBlocks
    ) internal view returns (uint256 ema, uint64 lastBlock, uint64 updateCount, bool reliable) {
        ema = $.ema;
        lastBlock = $.lastBlock;
        updateCount = $.updateCount;
        reliable = updateCount >= minBlocks;
    }

    /*//////////////////////////////////////////////////////////////
                          CONFIG-ACCEPTING OVERLOADS
    //////////////////////////////////////////////////////////////*/

    /// @notice Update EMA using Config (resolves alpha from config with default fallback)
    /// @param $ Storage pointer to EMA state
    /// @param newPrice New price observation (WAD scaled)
    /// @param config Per-token EMA configuration
    function update(
        EmaState storage $,
        uint256 newPrice,
        Config memory config
    ) internal {
        update($, newPrice, effectiveAlpha(config.alpha));
    }

    /// @notice Validate spot price against EMA using Config (resolves minBlocks from config)
    /// @param $ Storage pointer to EMA state
    /// @param spotPrice Current spot price to validate (WAD)
    /// @param maxDeviationBPS Maximum allowed deviation in basis points
    /// @param config Per-token EMA configuration
    function validate(
        EmaState storage $,
        uint256 spotPrice,
        uint256 maxDeviationBPS,
        Config memory config
    ) internal view {
        validate($, spotPrice, maxDeviationBPS, effectiveMinBlocks(config.minBlocks));
    }

    /// @notice Check if EMA is reliable using Config (resolves minBlocks from config)
    /// @param $ Storage pointer to EMA state
    /// @param config Per-token EMA configuration
    /// @return True if enough updates have occurred
    function isReliable(
        EmaState storage $,
        Config memory config
    ) internal view returns (bool) {
        return isReliable($, effectiveMinBlocks(config.minBlocks));
    }

    /// @notice Get full EMA state using Config (resolves minBlocks from config)
    /// @param $ Storage pointer to EMA state
    /// @param config Per-token EMA configuration
    function getState(
        EmaState storage $,
        Config memory config
    ) internal view returns (uint256 ema, uint64 lastBlock, uint64 updateCount, bool reliable) {
        return getState($, effectiveMinBlocks(config.minBlocks));
    }

    /// @notice Resolves the effective EMA alpha, falling back to default when zero
    /// @param tokenAlpha The token-specific alpha (0 = use default)
    function effectiveAlpha(
        uint64 tokenAlpha
    ) internal pure returns (uint64) {
        return tokenAlpha > 0 ? tokenAlpha : DEFAULT_ALPHA;
    }

    /// @notice Resolves the effective EMA minBlocks, falling back to default when zero
    /// @param tokenMinBlocks The token-specific minBlocks (0 = use default)
    function effectiveMinBlocks(
        uint16 tokenMinBlocks
    ) internal pure returns (uint16) {
        return tokenMinBlocks > 0 ? tokenMinBlocks : DEFAULT_MIN_BLOCKS;
    }

    /// @notice Calculate absolute deviation between two prices in basis points
    /// @param price1 First price (WAD)
    /// @param price2 Second price (WAD)
    /// @return Deviation in basis points (0 if price2 is zero)
    function calculateDeviationBPS(
        uint256 price1,
        uint256 price2
    ) internal pure returns (uint256) {
        if (price2 == 0) return 0;

        uint256 deviation;
        if (price1 > price2) {
            deviation = price1 - price2;
        } else {
            deviation = price2 - price1;
        }

        return (deviation * BPS) / price2;
    }
}

